function parseUA(ua){
  ua=String(ua||'').trim();
  if(!ua) throw new Error('UA 不能为空');
  var r={browser:'未知',browserVersion:'',engine:'未知',os:'未知',osVersion:'',device:'桌面',bot:false};
  var m;
  if(/bot|crawler|spider|slurp|bingpreview|facebookexternalhit/i.test(ua)){ r.bot=true; r.device='爬虫'; }
  if((m=ua.match(/Windows NT ([\d.]+)/))){ r.os='Windows'; var NT={'10.0':'10/11','6.3':'8.1','6.2':'8','6.1':'7'}; r.osVersion=NT[m[1]]||('NT '+m[1]); }
  else if((m=ua.match(/iPhone OS ([\d_]+)/))){ r.os='iOS'; r.osVersion=m[1].replace(/_/g,'.'); r.device='手机'; }
  else if((m=ua.match(/iPad; CPU OS ([\d_]+)/))){ r.os='iPadOS'; r.osVersion=m[1].replace(/_/g,'.'); r.device='平板'; }
  else if((m=ua.match(/Mac OS X ([\d_.]+)/))){ r.os='macOS'; r.osVersion=m[1].replace(/_/g,'.'); }
  else if((m=ua.match(/Android ([\d.]+)/))){ r.os='Android'; r.osVersion=m[1]; r.device=/Mobile/.test(ua)?'手机':'平板'; }
  else if(/CrOS/.test(ua)){ r.os='ChromeOS'; }
  else if(/Linux/.test(ua)){ r.os='Linux'; }
  if((m=ua.match(/Edg(?:e|A|iOS)?\/([\d.]+)/))){ r.browser='Edge'; r.browserVersion=m[1]; r.engine='Blink'; }
  else if((m=ua.match(/OPR\/([\d.]+)/))){ r.browser='Opera'; r.browserVersion=m[1]; r.engine='Blink'; }
  else if((m=ua.match(/SamsungBrowser\/([\d.]+)/))){ r.browser='Samsung Internet'; r.browserVersion=m[1]; r.engine='Blink'; }
  else if((m=ua.match(/MicroMessenger\/([\d.]+)/))){ r.browser='微信内置浏览器'; r.browserVersion=m[1]; r.engine='Blink'; }
  else if((m=ua.match(/UCBrowser\/([\d.]+)/))){ r.browser='UC 浏览器'; r.browserVersion=m[1]; r.engine='Blink'; }
  else if((m=ua.match(/Firefox\/([\d.]+)/))){ r.browser='Firefox'; r.browserVersion=m[1]; r.engine='Gecko'; }
  else if((m=ua.match(/CriOS\/([\d.]+)/))){ r.browser='Chrome (iOS)'; r.browserVersion=m[1]; r.engine='WebKit'; }
  else if((m=ua.match(/FxiOS\/([\d.]+)/))){ r.browser='Firefox (iOS)'; r.browserVersion=m[1]; r.engine='WebKit'; }
  else if((m=ua.match(/Chrome\/([\d.]+)/))){ r.browser='Chrome'; r.browserVersion=m[1]; r.engine='Blink'; }
  else if((m=ua.match(/Version\/([\d.]+).*Safari/))){ r.browser='Safari'; r.browserVersion=m[1]; r.engine='WebKit'; }
  else if(/Safari/.test(ua)){ r.browser='Safari'; r.engine='WebKit'; }
  else if((m=ua.match(/MSIE ([\d.]+)/))||/Trident/.test(ua)){ r.browser='IE'; r.browserVersion=m?m[1]:'11'; r.engine='Trident'; }
  if(r.engine==='未知'){
    if(/AppleWebKit/.test(ua)) r.engine='WebKit';
    else if(/Gecko\//.test(ua)) r.engine='Gecko';
  }
  return r;
}
function formatUA(r){
  var L=[];
  L.push('浏览器: '+r.browser+(r.browserVersion?' '+r.browserVersion:''));
  L.push('内核: '+r.engine);
  L.push('系统: '+r.os+(r.osVersion?' '+r.osVersion:''));
  L.push('设备类型: '+r.device);
  if(r.bot) L.push('识别为爬虫 / 机器人');
  return L.join('\n');
}
if (typeof module !== 'undefined' && module.exports) {
  module.exports = { parseUA:parseUA, formatUA:formatUA };
}
if (typeof window !== 'undefined') {
  window.UAForgePure = { parseUA:parseUA, formatUA:formatUA };
}
